    q18160: { h: "9eaa18749451", text: "A grass-cutting and cleaning team along with a solar park is a neighbour of the panels: would you enjoy park and cleaning together?" },
    q18161: { h: "40f6e210eb09", text: "A road strengthening team next to a wind site is the link for heavy loads: would you like the wind-and-road neighbourhood?" },
